'use client';

import { useState } from 'react';
import Image from 'next/image';
import { Coffee } from 'lucide-react';
import styles from './ImageGallery.module.css';

interface ImageGalleryProps {
    images: string[];
    altText: string;
}

export default function ImageGallery({ images, altText }: ImageGalleryProps) {
    const [selectedIndex, setSelectedIndex] = useState(0);

    // 이미지 URL 생성 함수
    const getImageUrl = (src: string) => {
        return src.startsWith('http') ? src : `http://localhost:8080/${src}`;
    };

    // 이미지가 없는 경우
    if (!images || images.length === 0) {
        return (
            <section className={styles.imageSection}>
                <div className={styles.mainImageWrapper}>
                    <div className={styles.placeholder}>
                        <Coffee size={64} />
                        <span>이미지 없음</span>
                    </div>
                </div>
            </section>
        );
    }

    const mainImage = images[selectedIndex];

    return (
        <section className={styles.imageSection}>
            {/* 메인 이미지 */}
            <div className={styles.mainImageWrapper}>
                <Image
                    src={getImageUrl(mainImage)}
                    alt={altText}
                    fill
                    className={styles.mainImage}
                    priority
                />
            </div>

            {/* 썸네일 목록 (이미지가 2개 이상일 때만 표시) */}
            {images.length > 1 && (
                <div className={styles.thumbnailList}>
                    {images.map((img, idx) => (
                        <button
                            key={idx}
                            className={`${styles.thumbnail} ${idx === selectedIndex ? styles.active : ''}`}
                            onClick={() => setSelectedIndex(idx)}
                        >
                            <Image
                                src={getImageUrl(img)}
                                alt={`${altText} ${idx + 1}`}
                                fill
                                className={styles.thumbnailImage}
                            />
                        </button>
                    ))}
                </div>
            )}
        </section>
    );
}
