'use client';

import styles from './BasicInfo.module.css';

interface BasicInfoProps {
    korName: string;
    engName: string;
    description: string;
    price: string;
    categoryName: string | null;
    isAvailable: boolean;
    isSoldOut: boolean;
}

export default function BasicInfo({
    korName,
    engName,
    description,
    price,
    categoryName,
    isAvailable,
    isSoldOut,
}: BasicInfoProps) {
    const formatPrice = (priceStr: string) => {
        const numPrice = parseFloat(priceStr);
        return new Intl.NumberFormat('ko-KR').format(numPrice);
    };

    const getStatusBadge = () => {
        if (isSoldOut) {
            return <span className={`${styles.badge} ${styles.soldOut}`}>품절</span>;
        }
        if (!isAvailable) {
            return <span className={`${styles.badge} ${styles.hidden}`}>숨김</span>;
        }
        return <span className={`${styles.badge} ${styles.active}`}>판매중</span>;
    };

    return (
        <section className={styles.infoSection}>
            {/* 헤더: 이름 & 상태 */}
            <div className={styles.header}>
                <div className={styles.titleGroup}>
                    <h1 className={styles.korName}>{korName}</h1>
                    <p className={styles.engName}>{engName}</p>
                </div>
                <div className={styles.badges}>
                    {categoryName && (
                        <span className={`${styles.badge} ${styles.category}`}>
                            {categoryName}
                        </span>
                    )}
                    {getStatusBadge()}
                </div>
            </div>

            {/* 가격 */}
            <div className={styles.infoBlock}>
                <span className={styles.blockTitle}>가격</span>
                <span className={styles.price}>₩{formatPrice(price)}</span>
            </div>

            {/* 설명 */}
            <div className={styles.infoBlock}>
                <span className={styles.blockTitle}>설명</span>
                <p className={styles.description}>
                    {description || '설명이 없습니다.'}
                </p>
            </div>
        </section>
    );
}
